jQuery(function($){let availableChildren={};function getCurrentLanguage(){return $('#adv-project-filters-form').data('lang')||''}
function updateCarousel(){const form=$('#adv-project-filters-form');const elementorWidget=$('#adv-project-carousel-wrapper');const carouselWrapper=elementorWidget.find('.swiper-wrapper');const swiperContainer=elementorWidget.find('.swiper');let templateId=form.data('template-id');if(!templateId||templateId===''){templateId=elementorWidget.find('.e-loop-item').first().data('elementor-id')}
if(!templateId)return;let dataStr=form.serialize()+'&action=adv_filter_projects&nonce='+adv_project_filter_vars.nonce+'&template_id='+templateId+'&lang='+getCurrentLanguage();$.ajax({url:adv_project_filter_vars.ajax_url,type:'POST',data:dataStr,beforeSend:function(){swiperContainer.css({'opacity':'0.3','transition':'opacity 0.3s'})},success:function(response){const swiperInstance=swiperContainer.data('swiper')||elementorWidget.data('swiper');if(swiperInstance&&typeof swiperInstance.destroy==='function'){swiperInstance.destroy(!0,!0)}
swiperContainer.removeClass('swiper-initialized swiper-horizontal swiper-pointer-events swiper-backface-hidden');carouselWrapper.html(response);swiperContainer.css('opacity','1');if(window.elementorFrontend&&window.elementorFrontend.elementsHandler){elementorFrontend.elementsHandler.runReadyTrigger(elementorWidget[0])}},error:function(){swiperContainer.css('opacity','1')}})}
function updateProjectTypeDropdowns(){const locationId=$('#filter-location').val();const parentTypeSelect=$('#filter-parent-type');const childTypeSelect=$('#filter-child-type');$.ajax({url:adv_project_filter_vars.ajax_url,type:'POST',data:{action:'adv_get_dependent_project_types',nonce:adv_project_filter_vars.nonce,location:locationId,lang:getCurrentLanguage()},beforeSend:function(){parentTypeSelect.prop('disabled',!0);childTypeSelect.prop('disabled',!0)},success:function(response){if(response.success){const parents=response.data.parents;availableChildren=response.data.children;parentTypeSelect.html('<option value="">'+adv_project_filter_vars.labels.project_type+'</option>');if(parents.length>0){parents.forEach(function(term){parentTypeSelect.append(`<option value="${term.id}">${term.name}</option>`)});parentTypeSelect.prop('disabled',!1)}else{parentTypeSelect.prop('disabled',!0)}
childTypeSelect.html('<option value="">'+adv_project_filter_vars.labels.types+'</option>');childTypeSelect.prop('disabled',!0);updateCarousel()}},complete:function(){if(parentTypeSelect.find('option').length>1){parentTypeSelect.prop('disabled',!1)}}})}
function updateChildDropdown(){const parentId=$('#filter-parent-type').val();const childSelect=$('#filter-child-type');childSelect.html('<option value="">'+adv_project_filter_vars.labels.types+'</option>');if(parentId&&availableChildren[parentId]){availableChildren[parentId].forEach(function(child){childSelect.append(`<option value="${child.id}">${child.name}</option>`)});childSelect.prop('disabled',!1)}else{childSelect.prop('disabled',!0)}}
$(document).on('change','#adv-project-filters-form #filter-location',function(){updateProjectTypeDropdowns()});$(document).on('change','#adv-project-filters-form #filter-parent-type',function(){updateChildDropdown();updateCarousel()});$(document).on('change','#adv-project-filters-form #filter-child-type',function(){updateCarousel()})})